// Asteroid Miner minimal implementation
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas element with id "game" not found.');
    return;
  }
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.clientWidth;
  canvas.height = canvas.clientHeight;

  // --- Game state ---
  const ship = {
    x: canvas.width / 2,
    y: canvas.height - 60,
    radius: 15,
    speed: 4,
    shield: 100,
    color: '#0ff',
  };
  const keys = {};
  const minerals = [];
  const asteroids = [];
  let score = 0;
  let gameOver = false;

  // --- Input handling ---
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // --- Helper functions ---
  function randRange(min, max) {
    return Math.random() * (max - min) + min;
  }
  function spawnMineral() {
    minerals.push({
      x: randRange(20, canvas.width - 20),
      y: -20,
      radius: 8,
      speed: 1.5,
    });
  }
  function spawnAsteroid() {
    const size = randRange(12, 30);
    const side = Math.random() < 0.5 ? 'left' : 'right';
    const x = side === 'left' ? -size : canvas.width + size;
    const y = randRange(0, canvas.height / 2);
    const speedX = side === 'left' ? randRange(1, 2.5) : -randRange(1, 2.5);
    const speedY = randRange(0.5, 1.5);
    asteroids.push({ x, y, radius: size, speedX, speedY });
  }
  function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = ship.color;
    ctx.beginPath();
    ctx.moveTo(0, -ship.radius);
    ctx.lineTo(ship.radius, ship.radius);
    ctx.lineTo(-ship.radius, ship.radius);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  function drawCircle(obj, col) {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.arc(obj.x, obj.y, obj.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  function drawHUD() {
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Shield: ${ship.shield}`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f44';
      ctx.textAlign = 'center';
      ctx.font = '32px monospace';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }
  function update() {
    if (gameOver) return;
    // Move ship
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    if (keys.ArrowUp) ship.y -= ship.speed;
    if (keys.ArrowDown) ship.y += ship.speed;
    // Keep within bounds
    ship.x = Math.max(ship.radius, Math.min(canvas.width - ship.radius, ship.x));
    ship.y = Math.max(ship.radius, Math.min(canvas.height - ship.radius, ship.y));

    // Update minerals
    for (let i = minerals.length - 1; i >= 0; i--) {
      const m = minerals[i];
      m.y += m.speed;
      // check collection
      const dx = m.x - ship.x;
      const dy = m.y - ship.y;
      if (Math.hypot(dx, dy) < m.radius + ship.radius) {
        score += 10;
        minerals.splice(i, 1);
        continue;
      }
      // remove if off‑screen
      if (m.y - m.radius > canvas.height) minerals.splice(i, 1);
    }
    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.speedX;
      a.y += a.speedY;
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      if (Math.hypot(dx, dy) < a.radius + ship.radius) {
        ship.shield -= 20;
        asteroids.splice(i, 1);
        if (ship.shield <= 0) {
          gameOver = true;
        }
        continue;
      }
      if (a.x + a.radius < 0 || a.x - a.radius > canvas.width || a.y - a.radius > canvas.height) {
        asteroids.splice(i, 1);
      }
    }
    // Spawn timers
    if (Math.random() < 0.02) spawnMineral(); // ~1 per 50 frames
    if (Math.random() < 0.01) spawnAsteroid(); // ~1 per 100 frames
  }
  function render() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // simple starfield background
    ctx.fillStyle = '#444';
    for (let i = 0; i < 50; i++) {
      ctx.fillRect(randRange(0, canvas.width), randRange(0, canvas.height), 1, 1);
    }
    // draw entities
    minerals.forEach(m => drawCircle(m, '#ff0'));
    asteroids.forEach(a => drawCircle(a, '#a44'));
    drawShip();
    drawHUD();
  }
  function loop() {
    update();
    render();
    requestAnimationFrame(loop);
  }
  // start loop
  requestAnimationFrame(loop);
})();
